approach_1_cpp:
// Iterate C++ Program to print alternate elements
// of the array

#include <iostream>
#include <vector>
using namespace std;

vector<int> getAlternates(vector<int> &arr) {
    vector<int> res;

    // Iterate over all alternate elements 
    for(int i = 0; i < arr.size(); i += 2) {
    	res.push_back(arr[i]);
    }
    return res;
}

int main() {
    vector<int> arr = {10, 20, 30, 40, 50};
    vector<int> res = getAlternates(arr); 
    for(int x: res)
        cout << x << " ";
}

approach_1_java:
// Iterate Java Program to print alternate elements
// of the array

import java.util.*;

class GfG {
    static ArrayList<Integer> getAlternates(int[] arr) {
        ArrayList<Integer> res = new ArrayList<>();

        // Iterate over all alternate elements
        for (int i = 0; i < arr.length; i += 2) {
            res.add(arr[i]);
        }
        return res;
    }

    public static void main(String[] args) {
        int[] arr = {10, 20, 30, 40, 50};
        ArrayList<Integer> res = getAlternates(arr);
        for (int x : res) {
            System.out.print(x + " ");
        }
    }
}

approach_1_c:
// Iterate C Program to print alternate elements
// of the array

#include <stdio.h>

void getAlternates(int arr[], int n) {

    // Iterate over all alternate elements
    for(int i = 0; i < n; i += 2) {
        printf("%d ", arr[i]);
    }
}

int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int size = sizeof(arr) / sizeof(arr[0]);
    getAlternates(arr, size);
    return 0;
}

approach_1_csharp:
// Iterate C# Program to print alternate elements
// of the array

using System;
using System.Collections.Generic;

class GfG {
    static List<int> getAlternates(int[] arr) {
        List<int> res = new List<int>();

        // Iterate over all alternate elements
        for (int i = 0; i < arr.Length; i += 2) {
            res.Add(arr[i]);
        }
        return res;
    }

    static void Main() {
        int[] arr = { 10, 20, 30, 40, 50 };
        List<int> res = getAlternates(arr);
        foreach (int x in res) {
            Console.Write(x + " ");
        }
    }
}

